	@Test
	void failedShutdownReportsThatTheConfigWasSavedAndDropsTheBrokenInstance() throws Exception {
		AtomicBoolean failShutdown = new AtomicBoolean(true);
		AtomicInteger created = new AtomicInteger();
		LocalRepositoryManager manager = new LocalRepositoryManager(directory.toFile()) {
			@Override
			protected Repository createRepository(String id) {
				created.incrementAndGet();
				SailRepository repository = new SailRepository(new MemoryStore()) {
					@Override
					protected void shutDownInternal() {
						if (failShutdown.get()) {
							throw new RepositoryException("Deliberate shutdown failure");
						}
						super.shutDownInternal();
					}
				};
				repository.init();
				return repository;
			}
		};
		manager.init();
		try {
			manager.addRepositoryConfig(config("target", "Before"));
			Repository previous = manager.getRepository("target");
			ConfigController controller = new ConfigController();
			controller.setRepositoryManager(manager);
			MockHttpServletRequest request = post(config("target", "After"));
			request.addParameter("restart", "true");

			assertThatThrownBy(() -> controller.handleRequest(request, new MockHttpServletResponse()))
					.hasMessageContaining("saved")
					.hasMessageContaining("shut down");

			assertThat(manager.getRepositoryConfig("target").getTitle()).isEqualTo("After");
			// The update itself initializes nothing after the failure, but the instance that could not shut down is
			// out of the cache: it must not keep serving the old configuration. The next request opens the saved one.
			assertThat(created).hasValue(1);
			Repository replacement = manager.getRepository("target");
			assertThat(replacement).isNotSameAs(previous);
			assertThat(replacement.isInitialized()).isTrue();
			assertThat(created).hasValue(2);
		} finally {
			failShutdown.set(false);
			manager.shutDown();
		}
	}

	@ParameterizedTest
	@MethodSource("invalidConfigurations")
	void invalidConfigurationsDoNotSaveOrStopTheLiveRepository(String submitted) throws Exception {
		LocalRepositoryManager manager = new LocalRepositoryManager(directory.toFile());
		manager.init();
		try {
			manager.addRepositoryConfig(config("target", "Before"));
			Repository previous = manager.getRepository("target");
			ConfigController controller = new ConfigController();
			controller.setRepositoryManager(manager);
			MockHttpServletRequest request = post(config("target", "After"));
			request.setContent(submitted.getBytes(StandardCharsets.UTF_8));
			request.addParameter("restart", "true");

			assertThatThrownBy(() -> controller.handleRequest(request, new MockHttpServletResponse()))
					.isInstanceOf(ClientHTTPException.class);

			assertThat(manager.getRepositoryConfig("target").getTitle()).isEqualTo("Before");
			assertThat(manager.getRepository("target")).isSameAs(previous);
			assertThat(previous.isInitialized()).isTrue();
			assertThat(manager.hasRepositoryConfig("other")).isFalse();
		} finally {
			manager.shutDown();
		}
	}

	static Stream<String> invalidConfigurations() {
		var two = new LinkedHashModel();
		config("target", "After").export(two);
		config("other", "Other").export(two);
		StringWriter multiple = new StringWriter();
		Rio.write(two, multiple, RDFFormat.TURTLE);
		String valid = new String(post(config("target", "After")).getContentAsByteArray(), StandardCharsets.UTF_8);
		return Stream.of("", "this is not Turtle", valid.replace("target", "other"), multiple.toString(),
				valid.replace("openrdf:SailRepository", "unknown:Repository"));
	}

