	@Test
	void aProxyResolvesTheReplacementInsteadOfReinitializingItsOldTarget() throws Exception {
		LocalRepositoryManager manager = new LocalRepositoryManager(directory.toFile());
		manager.init();
		try {
			manager.addRepositoryConfig(config("target", "Before"));
			manager.addRepositoryConfig(new RepositoryConfig("proxy", new ProxyRepositoryConfig("target")));
			Repository previous = manager.getRepository("target");
			Repository proxy = manager.getRepository("proxy");
			try (var connection = proxy.getConnection()) {
				connection.add(SimpleValueFactory.getInstance().createIRI("urn:subject"),
						SimpleValueFactory.getInstance().createIRI("urn:predicate"),
						SimpleValueFactory.getInstance().createLiteral("kept"));
			}
			previous.shutDown();
			Repository replacement = manager.getRepository("target");

			try (var connection = proxy.getConnection()) {
				assertThat(connection.size()).isEqualTo(1);
			}
			assertThat(replacement.isInitialized()).isTrue();
			assertThat(previous.isInitialized()).as("the proxy must not reopen the obsolete target").isFalse();
		} finally {
			manager.shutDown();
		}
	}

