	@Test
	void savingAndRestartingRecreatesOnlyTheTargetRepositoryWithoutDeletingItsData() throws Exception {
		LocalRepositoryManager manager = new LocalRepositoryManager(directory.toFile());
		manager.init();
		try {
			manager.addRepositoryConfig(config("target", "Before"));
			manager.addRepositoryConfig(config("untouched", "Untouched"));
			Repository previous = manager.getRepository("target");
			Repository untouched = manager.getRepository("untouched");
			var vf = SimpleValueFactory.getInstance();
			try (var connection = previous.getConnection()) {
				connection.add(vf.createIRI("urn:subject"), vf.createIRI("urn:predicate"), vf.createLiteral("kept"));
			}
			ConfigController controller = new ConfigController();
			controller.setRepositoryManager(manager);
			MockHttpServletRequest request = post(new RepositoryConfig("target", "After",
					new SailRepositoryConfig(new MemoryStoreConfig(true, 321))));
			request.addParameter("restart", "true");

			controller.handleRequest(request, new MockHttpServletResponse());

			assertThat(previous.isInitialized()).as("the actual server repository is shut down").isFalse();
			Repository active = manager.getRepository("target");
			assertThat(active).isNotSameAs(previous);
			assertThat(active.isInitialized()).isTrue();
			assertThat(((MemoryStore) ((SailRepository) active).getSail()).getSyncDelay()).isEqualTo(321);
			assertThat(manager.getRepositoryConfig("target").getTitle()).isEqualTo("After");
			assertThat(manager.getRepository("untouched")).isSameAs(untouched);
			try (var connection = active.getConnection()) {
				assertThat(connection.hasStatement(vf.createIRI("urn:subject"), vf.createIRI("urn:predicate"),
						vf.createLiteral("kept"), false)).isTrue();
			}
		} finally {
			manager.shutDown();
		}
	}

	private static RepositoryConfig config(String id, String title) {
		return new RepositoryConfig(id, title, new SailRepositoryConfig(new MemoryStoreConfig(true)));
	}

	static MockHttpServletRequest post(RepositoryConfig config) {
		var model = new LinkedHashModel();
		config.export(model);
		StringWriter turtle = new StringWriter();
		Rio.write(model, turtle, RDFFormat.TURTLE);
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/repositories/target/config");
		request.setAttribute("repositoryID", "target");
		request.setContentType(RDFFormat.TURTLE.getDefaultMIMEType());
		request.setContent(turtle.toString().getBytes(StandardCharsets.UTF_8));
		return request;
	}
